input.command:
cd /app; cat > tests/rounding_test.sh <<'EOF'
#!/bin/bash
# PRC-501: member price is 10% off, rounded DOWN (999 -> 899).
fail=0
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
[ "$(bash lib/statement.sh 999)" = "statement member 899" ] || { echo "statement 999"; fail=1; }
exit $fail
EOF
bash tests/rounding_test.sh; echo exit=$?
sed -i 's/(\(\$1 \* 90\) + 99) \/ 100/\1 \/ 100/' bin/price bin/quote lib/invoice.sh lib/statement.sh
grep -rn "90" bin lib; bash scripts/verify.sh; echo exit=$?; grep -rn "99) / 100" . --include=* -r --exclude-dir=.git | wc -l
